xql_query:
// ============================================================
// Rule: MS_Users Added to Global or Device Admin Roles
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with MS_Users Added to Global or Device Admin Roles.
// Severity: SEV_030_MEDIUM
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1098.003 - Account Manipulation: Add Office 365 Global Administrator Role

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variações de caixa em strings (ex.: operationName)
config case_sensitive = false

// Fonte de dados: logs brutos do Microsoft Azure / Entra ID
// O dataset 'msft_azure_raw' contém eventos de auditoria e atividades administrativas
| dataset = msft_azure_raw

// Extração/normalização de campos do objeto 'properties' (JSON)
// - properties_category: categoria do evento (ex.: RoleManagement)
// - properties_operationName: nome/descrição da operação executada
// - properties_targetResources: conteúdo com os recursos/entidades alvo (pode conter IDs de roles/objetos)
| alter
    properties_category        = json_extract_scalar(properties, "$.category"),
    properties_operationName   = json_extract_scalar(properties, "$.operationName"),
    properties_targetResources = json_extract_scalar(properties, "$.targetResources")

// Filtro: monitora adição de membro a role (RoleManagement)
// Condições:
// 1) category = RoleManagement
// 2) operationName contém "Add" e "member to role" (adição de membro a role)
// 3) targetResources contém IDs específicos (roles/objetos monitorados)
| filter properties_category = "RoleManagement"
| filter (properties_operationName contains "Add" and properties_operationName contains "member to role")
| filter (
    properties_targetResources contains "7698a772-787b-4ac8-901f-60d6b08affd2" or
    properties_targetResources contains "62e90394-69f5-4237-9190-012177145e10"
)
